const MARCA_ALIAS = {"messenger (chat de facebook)":"messenger","zendesk chat":"zendesk","hubspot chat":"hubspot","zoho salesiq":"zoho","watson assistant":"watson","microsoft copilot studio":"copilotstudio","elfsight ai chatbot":"elfsight","gohighlevel (conversation ai)":"gohighlevel","yellow.ai":"yellowai","tawk.to":"tawkto","respond.io":"respondio","joinchat (whatsapp)":"joinchat","click to chat (whatsapp)":"clicktochat","getbutton (whatsapp)":"getbutton","whatsapp flotante":"whatsapp","x (twitter)":"x","twitter":"x","google ads":"googleads","google analytics":"googleanalytics","analytics":"googleanalytics","google tag manager":"googletagmanager","google maps":"googlemaps","bio.link":"biolink","just eat":"justeat","uber eats":"ubereats","didi food":"didifood","el tenedor":"eltenedor","mesa 24/7":"mesa247","píxel de meta":"meta","google analytics 4":"googleanalytics","universal analytics":"googleanalytics","píxel de tiktok":"tiktok","linkedin insight":"linkedin","pinterest tag":"pinterest","píxel de snapchat":"snapchat","píxel de x (twitter)":"x","microsoft ads (uet)":"microsoft","microsoft clarity":"clarity","floodlight (campaign manager)":"googlecampaignmanager360","google adsense":"googleadsense","yandex metrica":"yandex","plausible":"plausibleanalytics","brevo (sendinblue)":"brevo","cookieyes (cookie law info)":"cookieyes","cookie notice":"cookienotice","borlabs cookie":"borlabscookie"};

// Clave de una marca a partir de su nombre ("Tawk.to", "Zendesk Chat"…); null si no tenemos su logo.
function claveMarca(nombre) {
  const n = String(nombre || "").trim().toLowerCase();
  const k = MARCA_ALIAS[n] || n.replace(/[^a-z0-9]/g, "");
  return MARCAS[k] ? k : null;
}

// HTML del logotipo oficial; si no lo hay, el icono genérico indicado (Lucide) o nada.
function marca(nombre, generico = "") {
  const k = claveMarca(nombre);
  if (!k) return generico ? `<i data-lucide="${generico}"></i>` : "";
  const m = MARCAS[k];
  if (m.img) return `<img class="logo-marca" src="${m.img}" alt="" title="${esc(nombreMarca(nombre))}" loading="lazy">`;
  const fill = k === "instagram" ? "url(#brand-ig)" : m.c;
  const defs = k === "instagram" ? '<defs><radialGradient id="brand-ig" cx="30%" cy="107%" r="150%"><stop offset="0" stop-color="#fdf497"/><stop offset=".05" stop-color="#fdf497"/><stop offset=".45" stop-color="#fd5949"/><stop offset=".6" stop-color="#d6249f"/><stop offset=".9" stop-color="#285AEB"/></radialGradient></defs>' : "";
  return `<svg class="logo-marca" viewBox="${m.vb}" role="img" aria-label="${m.t}"><title>${m.t}</title>${defs}<path fill="${fill}" d="${m.d}"/></svg>`;
}

function nombreMarca(nombre) { const k = claveMarca(nombre); return k && MARCAS[k].t ? MARCAS[k].t : String(nombre || ""); }
